output_text:
[
  {
    "id": "must_take_entrance_cart",
    "text": "At the start of a shopping trip, the agent is obliged to take the entrance cart rather than shop without it.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_cell": "at(1,5)",
        "cart_available_at_entrance": "cartAt(1,5)"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_cell",
              "cart_available_at_entrance",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "no_hand_shopping",
    "text": "Items should not be carried by hand; item pickup is permitted only while the agent has a cart.",
    "abstraction": {
      "state_properties": {
        "shopping_with_cart": "hasCart",
        "hands_occupied": "handFull"
      },
      "events": {
        "pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "handFull",
          "pickup_without_cart"
        ]
      }
    }
  },
  {
    "id": "return_cart_after_item_collection",
    "text": "After collecting any item with a cart, the agent is obliged to return the cart to the top-left return bay.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "cart_returned": "cartAt(0,1)"
      },
      "events": {
        "collect_item_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        },
        "leave_cart_at_return_bay": {
          "pre": {
            "and": [
              "return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_returned"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "collect_item_with_cart",
      "discharge": "leave_cart_at_return_bay"
    }
  },
  {
    "id": "cart_only_left_at_return_bay",
    "text": "The cart may only be put down at the designated return bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "outside_return_bay": {
          "not": "return_bay"
        }
      },
      "events": {
        "leave_cart_elsewhere": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "outside_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_elsewhere"
    }
  },
  {
    "id": "exit_only_after_cart_returned",
    "text": "The agent must not leave the store while still holding a cart or carrying goods by hand; exit is allowed only after the cart is parked.",
    "abstraction": {
      "state_properties": {
        "cart_returned": "cartAt(0,1)",
        "encumbered": {
          "or": [
            "hasCart",
            "handFull",
            {
              "not": "cart_returned"
            }
          ]
        }
      },
      "events": {
        "encumbered_exit": {
          "pre": {
            "and": [
              "EXIT",
              "encumbered"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "encumbered_exit"
    }
  },
  {
    "id": "no_cart_motion_from_return_bay",
    "text": "Once the cart reaches the top-left return bay, the agent may not push it onward; the only acceptable cart action there is to leave it.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "at_return_bay_with_cart": {
          "and": [
            "return_bay",
            "hasCart"
          ]
        }
      },
      "events": {
        "move_cart_from_return_bay": {
          "pre": {
            "and": [
              "at_return_bay_with_cart",
              "MOVE"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "move_cart_from_return_bay"
    }
  },
  {
    "id": "no_east_from_lower_far_right_with_cart",
    "text": "At the far-right lower shelf position, a shopper with a cart must turn back rather than continue east.",
    "abstraction": {
      "state_properties": {
        "lower_far_right_shelf_cell": "at(6,4)",
        "at_lower_far_right_with_cart": {
          "and": [
            "lower_far_right_shelf_cell",
            "hasCart"
          ]
        }
      },
      "events": {
        "pickup_at_lower_far_right": {
          "pre": {
            "and": [
              "at_lower_far_right_with_cart",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        },
        "continue_east_from_lower_far_right": {
          "pre": {
            "and": [
              "at_lower_far_right_with_cart",
              "E"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "continue_east_from_lower_far_right"
    }
  },
  {
    "id": "cart_return_marks_shopping_complete",
    "text": "After the cart has been parked in the return bay, the agent must not resume shopping or pick the cart back up.",
    "abstraction": {
      "state_properties": {
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "resume_after_return": {
          "pre": {
            "and": [
              "cart_parked_in_return_bay",
              {
                "or": [
                  "PICKUP_ITEM",
                  "PICKUP_CART"
                ]
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "resume_after_return"
    }
  }
]
